// Home "Components" stage, live panel: a small settings panel built from @rivetjs/ui. Client-only: ShowcaseStage.tsx
// mounts it on the first pointer / focus / touch on the stage; until then the server-rendered ShowcasePreview.tsx
// (this panel's markup, generated by scripts/showcase-preview.ts — rerun it after editing this file) paints the stage.
// CSS: home-ui.css (component styles, scoped theme) + home.css "Components showcase" (layout only).
import { signal } from "@rivetjs/reactivity";
import { Check } from "lucide";
import { Icon } from "@rivetjs/kit/icon";
import { Button } from "@rivetjs/ui/button";
import { Chip } from "@rivetjs/ui/chip";
import { Label } from "@rivetjs/ui/label";
import { ListBox } from "@rivetjs/ui/list-box";
import { Meter } from "@rivetjs/ui/meter";
import { Select } from "@rivetjs/ui/select";
import { Separator } from "@rivetjs/ui/separator";
import { Slider } from "@rivetjs/ui/slider";
import { Surface } from "@rivetjs/ui/surface";
import { Switch } from "@rivetjs/ui/switch";
import { ToggleButton } from "@rivetjs/ui/toggle-button";
import { ToggleButtonGroup } from "@rivetjs/ui/toggle-button-group";

const REGIONS = [
  { id: "eu-central", name: "Frankfurt" },
  { id: "eu-west", name: "Dublin" },
  { id: "us-east", name: "Virginia" },
  { id: "ap-south", name: "Mumbai" },
];
const FREQUENCIES = ["Daily", "Weekly", "Monthly"];

export function Showcase() {
  const saved = signal(false);
  return (
    <Surface class="lp-stage-panel">
        <div class="lp-stage-head">
          <span class="lp-stage-title">Workspace settings</span>
          <Chip color={saved() ? "success" : "default"} variant="soft" size="sm">
            {saved() ? "Saved" : "Draft"}
          </Chip>
        </div>
        <Switch defaultSelected onChange={() => saved.set(false)}>
          <Switch.Content>
            <Switch.Control>
              <Switch.Thumb />
            </Switch.Control>
            Notifications
          </Switch.Content>
        </Switch>
        <Slider defaultValue={60} onChange={() => saved.set(false)}>
          <Label>Volume</Label>
          <Slider.Output />
          <Slider.Track>
            <Slider.Fill />
            <Slider.Thumb />
          </Slider.Track>
        </Slider>
        <div class="lp-stage-field">
          <span class="lp-stage-label" id="lp-stage-digest">
            Digest
          </span>
          <ToggleButtonGroup
            aria-labelledby="lp-stage-digest"
            selectionMode="single"
            disallowEmptySelection
            defaultSelectedKeys={["Weekly"]}
            size="sm"
            onSelectionChange={() => saved.set(false)}
          >
            {FREQUENCIES.map((name) => (
              <ToggleButton id={name}>{name}</ToggleButton>
            ))}
          </ToggleButtonGroup>
        </div>
        <Select defaultValue="eu-central" onChange={() => saved.set(false)}>
          <Label>Region</Label>
          <Select.Trigger>
            <Select.Value />
            <Select.Indicator />
          </Select.Trigger>
          <Select.Popover>
            <ListBox>
              {REGIONS.map((region) => (
                <ListBox.Item id={region.id} textValue={region.name}>
                  {region.name}
                  <ListBox.ItemIndicator />
                </ListBox.Item>
              ))}
            </ListBox>
          </Select.Popover>
        </Select>
        <Separator />
        <Meter value={64} color="accent">
          <Label>Storage</Label>
          <Meter.Output />
          <Meter.Track>
            <Meter.Fill />
          </Meter.Track>
        </Meter>
        <div class="lp-stage-actions">
          <Button size="sm" onPress={() => saved.set(true)}>
            <Icon icon={Check} size={16} />
            Save
          </Button>
        </div>
    </Surface>
  );
}
